
from pathlib import Path
import numpy as np
from sklearn.datasets import fetch_olivetti_faces

ROOT = Path(__file__).resolve().parents[1]

def load_data():
    dataset = fetch_olivetti_faces()

    # Raw flattened pixels; no PCA.
    X = dataset.images.reshape(400, 4096)
    y = dataset.target.astype(np.int64)

    # Reuse the split already generated by data_setup.py.
    split = np.load(ROOT / "data/splits/olivetti_split.npz")
    train_idx = split["train_idx"]
    val_idx = split["val_idx"]
    test_idx = split["test_idx"]

    X_train, y_train = X[train_idx], y[train_idx]
    X_val, y_val = X[val_idx], y[val_idx]
    X_test, y_test = X[test_idx], y[test_idx]

    # Mask only the test images.
    X_test_images = dataset.images[test_idx].copy()
    X_test_images[:, 24:40, 24:40] = 0.0
    X_test_masked = X_test_images.reshape(-1, 4096)

    return {
        "X_train": X_train,
        "y_train": y_train,
        "X_val": X_val,
        "y_val": y_val,
        "X_test": X_test,
        "y_test": y_test,
        "X_test_masked": X_test_masked,
        "train_idx": train_idx,
        "val_idx": val_idx,
        "test_idx": test_idx,
        "X_all": X,
        "y_all": y,
        "seed": 26014,
    }


if __name__ == "__main__":
    data = load_data()
    for key in ["X_train", "X_val", "X_test", "X_test_masked"]:
        print(key, data[key].shape)
